const F=Finance,$=s=>document.querySelector(s),today=F.iso(new Date()),month=today.slice(0,7),uid=()=>crypto.randomUUID(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),dateLabel=s=>F.parse(s).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}),monthLabel=s=>F.parse(s+'-01').toLocaleDateString('pt-BR',{month:'long',year:'numeric'}),cents=v=>Math.round(Number(v)*100);
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',horizon:'M3 18 8 13l4 3 9-12M15 4h6v6',diary:'M4 3h14a2 2 0 0 1 2 2v16H6a2 2 0 0 1-2-2V3zm0 14h16M8 7h8M8 11h5',cards:'M3 5h18v14H3zM3 10h18M7 15h4',goals:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zm0 4a5 5 0 1 0 0 10 5 5 0 0 0 0-10zm0 4v2',reports:'M4 21V11h4v10M10 21V5h4v16M16 21V2h4v19',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm-9 4h2m14 0h2M12 3v2m0 14v2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.home}"/></svg>`;
const pages={home:'Visão geral',horizon:'Horizonte de saldos',diary:'Diário financeiro',cards:'Contas e cartões',goals:'Minhas economias',reports:'Resultados',settings:'Configurações'};
let page='home',selectedMonth=month,months=6,search='',filter='all',simulation=null;
const empty=()=>({version:1,demo:false,start:today,accounts:[{id:'cash',name:'Minha conta',balance:0}],cards:[],entries:[],paid:[],goals:[],daily:0,reserve:0});
function demo(){let s=empty();s.demo=true;s.start=month+'-01';s.accounts=[{id:'cash',name:'Conta principal',balance:325000},{id:'wallet',name:'Carteira',balance:15000}];s.cards=[{id:'purple',name:'Meu cartão',limit:800000,close:25,due:5}];const add=(name,amount,type,day,category,repeat='once',card='',count=1)=>{let t={id:uid(),name,amount,type,date:month+'-'+String(day).padStart(2,'0'),category,repeat,card,count,account:'cash',until:''};s.entries.push(t);if(t.date<=today&&!card)s.paid.push(t.id+':0')};add('Salário',620000,'income',5,'Trabalho','monthly');add('Projetos extras',140000,'income',20,'Trabalho','monthly');add('Aluguel',165000,'expense',10,'Casa','monthly');add('Internet + energia',28000,'expense',15,'Casa','monthly');add('Supermercado',42890,'expense',17,'Alimentação');add('Café da tarde',2850,'expense',21,'Alimentação');add('Combustível',18000,'expense',22,'Transporte');add('Assinaturas',5990,'expense',24,'Assinaturas','monthly','purple');add('Notebook',360000,'expense',12,'Compras','installments','purple',10);add('Jantar de sábado',14500,'expense',24,'Lazer');s.goals=[{id:uid(),name:'Reserva de emergência',target:2000000,saved:650000,date:F.addMonth(today,12)},{id:uid(),name:'Próxima viagem',target:500000,saved:180000,date:F.addMonth(today,6)}];s.daily=3500;s.reserve=100000;return s}
let state;try{state=JSON.parse(localStorage.getItem('aurion.v1'))||demo()}catch{state=demo()}
let dark=localStorage.getItem('aurion.theme')==='dark';document.body.classList.toggle('dark',dark);
function save(){try{localStorage.setItem('aurion.v1',JSON.stringify(state));return true}catch{toast('Não foi possível salvar. Exporte um backup agora.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function nav(){ $('#nav').innerHTML=Object.entries(pages).map(([id,label])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(id)}<span>${label}</span></button>`).join('');$('#crumb').textContent=pages[page].toLowerCase()}
function title(kicker,title,sub,actions=''){return `<div class="page-title"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
const newBtn=()=>'<button class="primary" data-action="entry">＋ Nova movimentação</button>';
function monthPicker(){return `<div class="month-control"><button data-action="prev" aria-label="Mês anterior">‹</button><span>${monthLabel(selectedMonth)}</span><button data-action="next" aria-label="Próximo mês">›</button></div>`}
function monthEntries(){return F.occurrences(state,selectedMonth+'-31').filter(t=>t.due.startsWith(selectedMonth)&&t.due>=state.start)}
function totals(){let es=monthEntries(),inc=es.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0),out=es.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0);return{inc,out,net:inc-out}}
function stat(label,value,note,style='',ic='horizon'){return `<div class="stat ${style}"><div class="stat-label">${label}${icon(ic)}</div><div class="value">${money(value)}</div><small>${note}</small></div>`}
function chart(points,comparison){let w=650,h=210,left=55,right=20,top=18,bottom=33,values=[...points.map(p=>p.value),...(comparison||[]).map(p=>p.value)],lo=Math.min(0,...values),hi=Math.max(10000,...values),span=hi-lo||1;const x=i=>left+i/(points.length-1||1)*(w-left-right),y=v=>top+(hi-v)/span*(h-top-bottom),coords=arr=>arr.map((p,i)=>`${x(i).toFixed(1)},${y(p.value).toFixed(1)}`).join(' ');let ticks=[0,1,2,3].map(i=>{let v=lo+span*i/3,yy=y(v);return `<line x1="${left}" y1="${yy}" x2="${w-right}" y2="${yy}" stroke="var(--line)" stroke-dasharray="3 5"/><text x="${left-10}" y="${yy+3}" text-anchor="end">${(v/100000).toLocaleString('pt-BR',{maximumFractionDigits:1})} mil</text>`}).join('');let marks=[0,.2,.4,.6,.8,1].map(p=>{let i=Math.round((points.length-1)*p);return `<text x="${x(i)}" y="${h-6}" text-anchor="middle">${dateLabel(points[i].date)}</text>`}).join('');return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Projeção diária de saldo de ${dateLabel(points[0].date)} até ${dateLabel(points.at(-1).date)}"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#96b78b" stop-opacity=".2"/><stop offset="1" stop-color="#96b78b" stop-opacity="0"/></linearGradient></defs>${ticks}<polygon points="${left},${h-bottom} ${coords(points)} ${w-right},${h-bottom}" fill="url(#fill)"/><polyline points="${coords(points)}" fill="none" stroke="#73946a" stroke-width="2.5" stroke-linejoin="round"/>${comparison?`<polyline points="${coords(comparison)}" fill="none" stroke="#c68c62" stroke-width="2" stroke-dasharray="5 4"/>`:''}${marks}${points.filter((_,i)=>i%Math.max(1,Math.floor(points.length/30))===0).map(p=>`<circle cx="${x(points.indexOf(p))}" cy="${y(p.value)}" r="7" fill="transparent"><title>${dateLabel(p.date)}: ${money(p.value)}</title></circle>`).join('')}</svg>`}
function projectionPanel(full=false){let pts=F.horizon(state,today,months,state.daily),min=pts.reduce((a,b)=>a.value<b.value?a:b),extra=simulation?[simulation]:[],cmp=simulation?F.horizon(state,today,months,state.daily,extra):null;return `<section class="panel"><div class="panel-head"><div><h2>Horizonte de saldos</h2><div class="sub">Um olhar para o que vem pela frente.</div></div><div class="segmented">${[3,6,12].map(n=>`<button class="${months===n?'selected':''}" data-months="${n}">${n} meses</button>`).join('')}</div></div><div class="chart-key"><span><i></i>Saldo projetado</span><span><i class="orange"></i>${simulation?'Com a simulação':'Inclui previsão diária'}</span></div>${chart(pts,cmp)}<div class="insight ${min.value<state.reserve?'warn':''}"><span>${min.value<state.reserve?'◷':'↗'}</span><span>Menor saldo previsto: <b class="money">${money(min.value)}</b> em ${dateLabel(min.date)}.${min.value<0?' Há risco de saldo negativo.':min.value<state.reserve?' Abaixo da sua margem de segurança.':' Dentro da sua margem de segurança.'}</span></div>${full?`<p class="note">Projeção = saldos iniciais + entradas − saídas e faturas − previsão diária de ${money(state.daily)}. A previsão diária representa gastos extras ainda não lançados. Não inclui rendimentos nem despesas desconhecidas.</p>`:''}</section>`}
function rows(entries,limit=6){if(!entries.length)return '<div class="empty"><strong>Nenhuma movimentação por aqui.</strong>Registre uma entrada ou saída para começar.</div>';return entries.slice(0,limit).map(t=>`<div class="row"><span class="entry-icon ${t.type}">${t.type==='income'?'↙':'↗'}</span><div class="grow"><strong>${esc(t.label)}</strong><small>${esc(t.category||'Sem categoria')} · ${dateLabel(t.due)}${t.card?' · cartão':''}</small></div><span class="pill ${t.paid?'':'pending'}">${t.paid?'Concluído':'Previsto'}</span><span class="money ${t.type==='income'?'up':''}">${t.type==='income'?'+':'−'} ${money(t.amount)}</span></div>`).join('')}
function goalRows(){return state.goals.length?state.goals.slice(0,3).map(g=>`<div class="goal"><div class="goal-title"><b>${esc(g.name)}</b><span>${Math.round(g.saved/g.target*100)}%</span></div><div class="progress"><i style="width:${Math.min(100,g.saved/g.target*100)}%"></i></div><small><span class="money">${money(g.saved)}</span> de <span class="money">${money(g.target)}</span></small></div>`).join(''):'<div class="empty">Dê um nome ao seu próximo objetivo.</div>'}
function home(){let t=totals(),pts=F.horizon(state,today,6,state.daily),min=Math.min(...pts.map(p=>p.value));return title('SEU DINHEIRO, DAQUI PRA FRENTE','Seu futuro começa hoje.','Um pouco de organização. Muito mais tranquilidade.',newBtn())+`<div class="stats">${stat('Saldo confirmado',F.balance(state,today,true),'Saldos iniciais + movimentações concluídas','hero','cards')}${stat('Entradas do mês',t.inc,'Previstas + confirmadas','','horizon')}${stat('Saídas do mês',t.out,'Inclui faturas · sem previsão diária','','diary')}${stat('Saldo em 6 meses',pts.at(-1).value,'Considerando a previsão diária','','goals')}</div><div class="two-col">${projectionPanel()}<section class="panel peace"><div class="eyebrow">UM PASSO DE CADA VEZ</div><div class="sunrise"></div><h3>${min>=state.reserve?'Seu amanhã tem espaço.':'Vamos cuidar do amanhã?'}</h3><p>Antes de uma nova compra, veja como ela conversa com os seus próximos meses.</p><button data-action="simulate">Posso comprar? <span>↗</span></button></section></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Seu diário financeiro</h2><div class="sub">Pequenos registros. Uma visão completa.</div></div><button class="text" data-page="diary">Ver tudo ↗</button></div>${rows(monthEntries().sort((a,b)=>b.due.localeCompare(a.due)),5)}</section><section class="panel"><div class="panel-head"><div><h2>Planos ganhando vida</h2><div class="sub">Cada passo conta.</div></div><button class="text" data-page="goals">↗</button></div>${goalRows()}<button class="text" data-action="goal">＋ Criar uma economia</button></section></div>`}
function horizon(){let pts=F.horizon(state,today,months,state.daily),end=pts.at(-1),min=pts.reduce((a,b)=>a.value<b.value?a:b);let summaries=[];for(let i=0;i<months;i++){let m=F.addMonth(today,i).slice(0,7),p=pts.filter(x=>x.date.startsWith(m));if(p.length)summaries.push({m,first:p[0],last:p.at(-1),min:Math.min(...p.map(x=>x.value))})}return title('OLHAR PARA FRENTE','Horizonte de saldos','Enxergue seu dinheiro dia a dia, antes de decidir.',`<button data-action="forecast">Ajustar previsão</button><button class="primary" data-action="simulate">Simular uma compra ↗</button>`)+`<div class="stats">${stat('Saldo projetado hoje',pts[0].value,'Inclui pendências e previsão de hoje','hero')}${stat('No fim do horizonte',end.value,dateLabel(end.date))}${stat('Menor saldo',min.value,dateLabel(min.date))}${stat('Margem de segurança',state.reserve,'Definida por você')}</div>${projectionPanel(true)}${simulation?`<div class="insight warn">Simulação: ${esc(simulation.name)} · ${money(simulation.amount)} em ${simulation.count} parcela(s). <button data-action="save-simulation">Registrar compra</button><button data-action="clear-simulation">Descartar</button></div>`:''}<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Mês a mês</h2><button data-action="export-horizon">Exportar projeção CSV</button></div><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Menor saldo</th><th>Saldo no fim do período</th><th>Horizonte</th></tr></thead><tbody>${summaries.map(p=>`<tr><td>${monthLabel(p.m)}</td><td class="money ${p.min<0?'down':''}">${money(p.min)}</td><td class="money">${money(p.last.value)}</td><td><span class="pill ${p.min<state.reserve?'pending':''}">${p.min<0?'Saldo negativo':p.min<state.reserve?'Atenção à margem':'Acima da margem'}</span></td></tr>`).join('')}</tbody></table></div><details open><summary class="note">Horizonte diário · verde: acima da margem · amarelo: atenção · vermelho: negativo</summary><div class="table-wrap" style="max-height:330px"><table><thead><tr><th>Dia</th><th>Saldo previsto</th></tr></thead><tbody>${pts.map(p=>`<tr><td>${dateLabel(p.date)}</td><td class="money ${p.value<0?'down':''}">${money(p.value)}</td></tr>`).join('')}</tbody></table></div></details></section>`}
function diary(){let es=monthEntries().filter(t=>(filter==='all'||t.type===filter)&&t.label.toLowerCase().includes(search.toLowerCase()));return title('UM CHECK-IN COM VOCÊ','Diário financeiro','Registre o que aconteceu. Planeje o que ainda vem.',newBtn())+`<section class="panel"><div class="filters">${monthPicker()}<input type="search" id="search" placeholder="Buscar movimentações…" value="${esc(search)}" aria-label="Buscar movimentações"><select id="type-filter" aria-label="Filtrar tipo"><option value="all">Todas</option><option value="income" ${filter==='income'?'selected':''}>Entradas</option><option value="expense" ${filter==='expense'?'selected':''}>Saídas</option></select><button data-action="export-csv">Exportar CSV</button></div><div class="table-wrap"><table><thead><tr><th>Vencimento</th><th>Movimentação</th><th>Categoria</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>${es.map(t=>`<tr><td>${dateLabel(t.due)}</td><td><strong>${esc(t.label)}</strong><div class="sub">${esc(t.card?state.cards.find(c=>c.id===t.card)?.name:state.accounts.find(a=>a.id===t.account)?.name||'Conta')}${t.repeat==='monthly'?' · mensal':''}</div></td><td>${esc(t.category||'—')}</td><td class="money ${t.type==='income'?'up':''}">${t.type==='income'?'+':'−'} ${money(t.amount)}</td><td><button data-paid="${esc(t.key)}" title="Alternar status">${t.paid?'✓ Concluído':'○ Previsto'}</button></td><td><button data-edit="${t.id}">Editar</button> <button class="danger" data-delete="${t.id}">Excluir</button></td></tr>`).join('')}</tbody></table>${!es.length?'<div class="empty">Nenhuma movimentação neste período.</div>':''}</div></section><p class="note">O status concluído altera o saldo confirmado. O horizonte considera também as movimentações previstas. Editar uma recorrência altera toda a série; para encerrá-la, defina uma data final.</p>`}
function cards(){return title('TUDO NO SEU LUGAR','Contas e cartões','Saldos, limites e próximas faturas, sem perder o contexto.',`<button data-action="account">＋ Conta</button><button class="primary" data-action="card">＋ Cartão</button>`)+`<div class="three-col">${state.accounts.map(a=>{let v=a.balance+F.occurrences(state,today).filter(t=>t.account===a.id&&t.due>=state.start&&t.due<=today&&t.paid).reduce((s,t)=>s+(t.type==='income'?t.amount:-t.amount),0);return `<section class="panel"><div class="panel-head"><h2>${esc(a.name)}</h2>${icon('cards')}</div><div class="sub">Saldo confirmado</div><div class="value">${money(v)}</div><button class="text" data-account="${a.id}">Editar saldo inicial ↗</button></section>`}).join('')}</div><div class="panel-head"><h2>Meus cartões</h2>${monthPicker()}</div><div class="three-col">${state.cards.map(c=>{let es=monthEntries().filter(t=>t.card===c.id),bill=es.reduce((s,t)=>s+t.amount,0);return `<div><div class="card-art"><h3>${esc(c.name)}</h3><small>Fatura prevista · ${monthLabel(selectedMonth)}</small><div class="value">${money(bill)}</div><div class="sub" style="color:#d2dfd5">Fecha dia ${c.close} · vence dia ${c.due}</div></div><section class="panel" style="margin-top:10px"><div class="sub">Limite cadastrado <b class="money">${money(c.limit)}</b></div><div class="progress"><i style="width:${Math.min(100,bill/c.limit*100)}%"></i></div><button class="text" data-card="${c.id}">Editar cartão ↗</button>${rows(es,4)}</section></div>`}).join('')||'<section class="panel empty"><strong>Seu primeiro cartão.</strong>Cadastre fechamento e vencimento para projetar as parcelas.</section>'}</div><p class="note">Compras no dia do fechamento entram na próxima fatura. Compras no cartão saem do saldo somente no vencimento. Marque cada item como concluído quando a fatura for paga. O limite exibido é cadastral; não é consulta ao banco.</p>`}
function goals(){return title('DÊ UM DESTINO AOS SEUS PLANOS','Minhas economias','Acompanhe os objetivos que fazem sentido para você.',`<button class="primary" data-action="goal">＋ Nova economia</button>`)+`<div class="three-col">${state.goals.map(g=>{let remaining=Math.max(0,g.target-g.saved),now=F.parse(today),target=F.parse(g.date),n=Math.max(1,(target.getFullYear()-now.getFullYear())*12+target.getMonth()-now.getMonth());return `<section class="panel"><div class="entry-icon">◎</div><h2 style="margin-top:20px">${esc(g.name)}</h2><div class="value">${money(g.saved)}</div><div class="sub">de ${money(g.target)} · até ${dateLabel(g.date)} / ${g.date.slice(0,4)}</div><div class="progress"><i style="width:${Math.min(100,100*g.saved/g.target)}%"></i></div><p class="note">${remaining?`Faltam <span class="money">${money(remaining)}</span>.<br>Referência mensal: <b class="money">${money(Math.ceil(remaining/n))}</b>.`:'Objetivo alcançado. Hora de celebrar!'}</p><button data-goal="${g.id}">Atualizar economia</button> <button class="text danger" data-remove-goal="${g.id}">Excluir</button></section>`}).join('')||'<div class="panel empty">Crie seu primeiro objetivo.</div>'}</div><div class="insight">As economias são um acompanhamento separado: atualizar o valor guardado não movimenta suas contas. Não some esse valor ao saldo se o dinheiro já estiver em uma conta cadastrada.</div>`}
function reports(){let t=totals(),by={};monthEntries().filter(e=>e.type==='expense').forEach(e=>by[e.category||'Sem categoria']=(by[e.category||'Sem categoria']||0)+e.amount);return title('ENTENDER PARA ESCOLHER','Seus resultados','Uma leitura simples dos números do mês.',`<button data-action="print">Imprimir / PDF</button>`)+`<div class="panel-head">${monthPicker()}</div><div class="stats">${stat('Entradas',t.inc,'Inclui valores previstos','hero')}${stat('Saídas',t.out,'Inclui valores previstos')}${stat('Resultado do mês',t.net,'Entradas − saídas')}${stat('Custo diário registrado',Math.round(t.out/new Date(+selectedMonth.slice(0,4),+selectedMonth.slice(5),0).getDate()),'Saídas ÷ dias do mês')}</div><div class="two-col"><section class="panel"><h2>Para onde vai seu dinheiro</h2><p class="sub">Categorias são opcionais. Clareza é o objetivo.</p>${Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="goal"><div class="goal-title"><span>${esc(k)}</span><b class="money">${money(v)}</b></div><div class="progress"><i style="width:${t.out?100*v/t.out:0}%"></i></div><small>${t.out?(100*v/t.out).toFixed(1):0}% das saídas</small></div>`).join('')||'<div class="empty">Sem saídas neste mês.</div>'}</section><section class="panel"><h2>Leitura do mês</h2><div class="sunrise"></div><p class="note">${t.inc?`O resultado equivale a <b>${(t.net/t.inc*100).toFixed(1)}%</b> das entradas previstas.`:'Cadastre suas entradas para calcular a relação entre receitas e despesas.'}</p><p class="note">Estes resultados consideram lançamentos e faturas, incluindo pendências. A previsão diária adicional aparece somente no horizonte, pois ainda não é um gasto registrado.</p><button data-page="horizon">Explorar o horizonte ↗</button></section></div>`}
function settings(){return title('DO SEU JEITO','Seu espaço financeiro','Preferências e dados sob seu controle.')+`<div class="settings-grid"><section class="panel"><h2>Seu ponto de partida</h2><p class="note">Os saldos iniciais representam o dinheiro no início de ${dateLabel(state.start)} / ${state.start.slice(0,4)}. Movimentações anteriores a essa data ficam fora dos saldos.</p><button data-action="start">Alterar data inicial</button><div class="help-section"><b>Previsão diária adicional</b><span class="money">${money(state.daily)}</span> por dia, a partir de hoje.</div><div class="help-section"><b>Margem de segurança</b><span class="money">${money(state.reserve)}</span></div><button class="text" data-action="forecast">Ajustar previsão e margem ↗</button></section><section class="panel"><h2>Backup e portabilidade</h2><p class="note">Os dados são salvos neste navegador, neste dispositivo. Limpar os dados do navegador pode apagá-los. Não há sincronização entre dispositivos nem conexão bancária nesta versão.</p><div class="actions"><button class="primary" data-action="backup">Baixar backup JSON</button><button data-action="restore">Restaurar backup</button><button data-action="export-csv">Exportar mês CSV</button></div></section><section class="panel"><h2>Aparência</h2><p class="note">Uma interface confortável em qualquer hora do dia.</p><button data-action="theme">Alternar tema claro / escuro</button><button class="text" data-action="privacy">Ocultar / mostrar valores</button></section><section class="panel"><h2>Começar de novo</h2><p class="note">Baixe um backup antes de substituir seus dados. A demonstração usa apenas números fictícios.</p><div class="actions"><button data-action="demo">Carregar demonstração</button><button class="danger" data-action="reset">Começar com dados vazios</button></div></section></div>`}
function render(){nav();$('#app').innerHTML=(state.demo?'<div class="demo"><span>✦ Modo demonstração · valores fictícios para explorar o Aurion</span><button data-action="reset">Começar com meus dados ↗</button></div>':'')+({home,horizon,diary,cards,goals,reports,settings}[page]||home)();}
function modal(title,body,submit){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Fechar">×</button></div><form id="modal-form">${body}<div class="form-actions"><button type="button" data-action="close">Cancelar</button><button class="primary" type="submit">${submit||'Salvar'}</button></div></form>`;if(!$('#dialog').open)$('#dialog').showModal()}
const field=(name,label,type,value,attrs='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
const select=(name,label,options,value)=>`<div class="field"><label for="f-${name}">${label}</label><select name="${name}" id="f-${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;
let handler=null;
function entry(id,sim=false){let t=state.entries.find(t=>t.id===id)||{name:'',amount:'',date:today,type:'expense',repeat:'once',count:1,account:state.accounts[0].id,category:'',card:'',until:''};modal(sim?'Posso comprar?':id?'Editar movimentação':'Nova movimentação',`<p class="note">${sim?'Teste o impacto sem alterar seu diário.':'Para parcelas, informe o valor total da compra. Para recorrência mensal, informe o valor de cada mês.'}</p><div class="form-grid">${field('name','Descrição','text',t.name,'required maxlength="100"')}${field('amount',sim?'Valor total (R$)':'Valor (R$)','number',t.amount?t.amount/100:'','required min="0.01" max="100000000" step="0.01"')}${select('type','Tipo',[['expense','Saída'],['income','Entrada']],t.type)}${field('date','Data da compra / movimentação','date',t.date,'required')}${select('repeat','Repetição',[['once','Uma vez'],['monthly','Todo mês'],['installments','Parcelado']],t.repeat)}${field('count','Número de parcelas','number',t.count,'min="1" max="360" required')}${select('account','Conta de pagamento / recebimento',state.accounts.map(a=>[a.id,a.name]),t.account)}${select('card','Forma de pagamento',[['','Direto na conta'],...state.cards.map(c=>[c.id,c.name])],t.card)}${field('category','Categoria (opcional)','text',t.category,'maxlength="50" list="categories"')}${field('until','Encerrar recorrência em (opcional)','date',t.until)}<datalist id="categories">${['Casa','Alimentação','Transporte','Trabalho','Lazer','Saúde','Compras','Assinaturas'].map(s=>`<option>${s}</option>`).join('')}</datalist></div><p class="sub">Editar uma série altera todas as ocorrências, inclusive anteriores. Para uma nova condição, encerre a série antiga e crie outra.</p>`,sim?'Ver impacto':'Salvar movimentação');handler=d=>{let item={id:id||uid(),name:d.name.trim(),amount:cents(d.amount),date:d.date,type:d.type,repeat:d.repeat,count:Number(d.count),account:d.account,card:d.card,category:d.category.trim(),until:d.until};if(item.type==='income'&&item.card)throw Error('Entradas devem ser recebidas diretamente em uma conta.');if(item.until&&item.until<item.date)throw Error('A data final precisa ser igual ou posterior à inicial.');if(item.repeat==='installments'&&item.amount<item.count)throw Error('O valor total precisa ser pelo menos um centavo por parcela.');if(item.date<state.start)throw Error('Use uma data a partir do saldo inicial ou ajuste a data inicial nas configurações.');if(sim){simulation=item;page='horizon'}else{state.entries=id?state.entries.map(x=>x.id===id?item:x):[...state.entries,item];save()}return true}}
function account(id){let a=state.accounts.find(a=>a.id===id)||{name:'',balance:0};modal(id?'Editar conta':'Nova conta',field('name','Nome','text',a.name,'required maxlength="60"')+field('balance','Saldo inicial (R$)','number',a.balance/100,'required step="0.01"')+`<p class="note">Saldo no início de ${dateLabel(state.start)}. Não é o saldo atual recalculado.</p>`);handler=d=>{let v={id:id||uid(),name:d.name.trim(),balance:cents(d.balance)};state.accounts=id?state.accounts.map(x=>x.id===id?v:x):[...state.accounts,v];save();return true}}
function card(id){let c=state.cards.find(c=>c.id===id)||{name:'',limit:0,close:25,due:5};modal(id?'Editar cartão':'Novo cartão',field('name','Nome do cartão','text',c.name,'required maxlength="60"')+`<div class="form-grid">${field('limit','Limite (R$)','number',c.limit/100,'required min="0.01" step="0.01"')}${field('close','Dia do fechamento','number',c.close,'required min="1" max="31"')}${field('due','Dia do vencimento','number',c.due,'required min="1" max="31"')}</div><p class="note">Alterar datas recalcula o vencimento de todas as compras vinculadas. Em meses curtos, usamos o último dia do mês.</p>`);handler=d=>{let v={id:id||uid(),name:d.name.trim(),limit:cents(d.limit),close:+d.close,due:+d.due};state.cards=id?state.cards.map(x=>x.id===id?v:x):[...state.cards,v];save();return true}}
function goal(id){let g=state.goals.find(g=>g.id===id)||{name:'',target:0,saved:0,date:F.addMonth(today,12)};modal(id?'Atualizar economia':'Nova economia',field('name','Nome do objetivo','text',g.name,'required maxlength="80"')+`<div class="form-grid">${field('target','Quanto quer alcançar (R$)','number',g.target/100,'required min="0.01" step="0.01"')}${field('saved','Quanto já guardou (R$)','number',g.saved/100,'required min="0" step="0.01"')}${field('date','Data desejada','date',g.date,'required')}</div><p class="note">Esse acompanhamento não altera os saldos das contas.</p>`);handler=d=>{let v={id:id||uid(),name:d.name.trim(),target:cents(d.target),saved:cents(d.saved),date:d.date};state.goals=id?state.goals.map(x=>x.id===id?v:x):[...state.goals,v];save();return true}}
function confirmAction(title,text,fn){modal(title,`<p class="note">${text}</p>`,'Confirmar');handler=()=>{fn();return true}}
function download(name,text,type){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(data){return '\ufeff'+data.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(';')).join('\r\n')}
function help(){modal('Um futuro mais claro.',`<div class="help-section"><b>1. Defina o ponto de partida</b>Cadastre suas contas e saldos na data inicial. Use a mesma data como referência para todas.</div><div class="help-section"><b>2. Coloque a vida no calendário</b>Registre receitas, contas fixas e parcelas. Marque como concluído o que já foi recebido ou pago.</div><div class="help-section"><b>3. Olhe para o horizonte</b>O saldo projetado considera também as pendências. A previsão diária é uma estimativa adicional para gastos que ainda não foram cadastrados.</div><div class="help-section"><b>4. Teste antes de decidir</b>Simule compras e compare os saldos. A projeção depende da exatidão e completude dos dados.</div><div class="help-section"><b>5. Cuide dos seus dados</b>Faça backups nas configurações. Dados locais não são sincronizados com bancos ou outros aparelhos.</div>`,'Entendi');handler=()=>true}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.page){page=d.page;render();window.scrollTo(0,0);return}if(d.months){months=+d.months;render();return}if(d.edit){entry(d.edit);return}if(d.account){account(d.account);return}if(d.card){card(d.card);return}if(d.goal){goal(d.goal);return}if(d.removeGoal){confirmAction('Excluir economia?','O objetivo será removido do acompanhamento. Nenhum saldo de conta será alterado.',()=>{state.goals=state.goals.filter(g=>g.id!==d.removeGoal);save()});return}if(d.delete){confirmAction('Excluir movimentação?','Todas as parcelas ou repetições desta série serão removidas. Exporte um backup nas configurações caso queira preservá-las.',()=>{state.entries=state.entries.filter(t=>t.id!==d.delete);state.paid=state.paid.filter(k=>!k.startsWith(d.delete+':'));save()});return}if(d.paid){let t=F.occurrences(state,'2099-12-31').find(t=>t.key===d.paid);if(t&&t.due>today){toast('Movimentação futura: ajuste a data para registrar uma antecipação.');return}state.paid=state.paid.includes(d.paid)?state.paid.filter(k=>k!==d.paid):[...state.paid,d.paid];save();render();return}
 switch(d.action){case'close':$('#dialog').close();break;case'entry':entry();break;case'account':account();break;case'card':card();break;case'goal':goal();break;case'simulate':entry(null,true);break;case'help':help();break;case'privacy':document.body.classList.toggle('hidden-values');break;case'theme':dark=!dark;document.body.classList.toggle('dark',dark);localStorage.setItem('aurion.theme',dark?'dark':'light');break;case'prev':case'next':selectedMonth=F.addMonth(selectedMonth+'-01',d.action==='prev'?-1:1).slice(0,7);render();break;case'clear-simulation':simulation=null;render();break;case'save-simulation':if(simulation){state.entries.push(simulation);simulation=null;save();render();toast('Compra registrada no diário.')}break;case'forecast':modal('Ajuste seu horizonte',field('daily','Previsão diária adicional (R$)','number',state.daily/100,'required min="0" step="0.01"')+field('reserve','Margem mínima de segurança (R$)','number',state.reserve/100,'required min="0" step="0.01"')+'<p class="note">Use a previsão diária apenas para despesas ainda não lançadas. Ela é descontada todos os dias a partir de hoje e não movimenta seu saldo confirmado.</p>');handler=d=>{state.daily=cents(d.daily);state.reserve=cents(d.reserve);save();return true};break;case'start':modal('Data do saldo inicial',field('date','Data de referência','date',state.start,'required')+'<p class="note">Movimentações anteriores deixam de compor o saldo. Revise também os saldos iniciais de suas contas.</p>');handler=d=>{if(d.date>today)throw Error('A data inicial não pode estar no futuro.');state.start=d.date;save();return true};break;case'backup':download('aurion-backup-'+today+'.json',JSON.stringify(state,null,2),'application/json');break;case'restore':$('#import-file').click();break;case'export-csv':download('aurion-diario-'+selectedMonth+'.csv',csv([['Data','Descrição','Tipo','Categoria','Valor R$','Status'],...monthEntries().map(t=>[t.due,t.label,t.type==='income'?'Entrada':'Saída',t.category,(t.amount/100).toFixed(2).replace('.',','),t.paid?'Concluído':'Previsto'])]),'text/csv;charset=utf-8');break;case'export-horizon':download('aurion-horizonte-'+today+'.csv',csv([['Data','Saldo previsto R$'],...F.horizon(state,today,months,state.daily).map(p=>[p.date,(p.value/100).toFixed(2).replace('.',',')])]),'text/csv;charset=utf-8');break;case'print':window.print();break;case'reset':case'demo':confirmAction('Substituir dados atuais?', 'Esta ação substitui os dados deste navegador. Baixe um backup antes de confirmar. '+(d.action==='reset'?'Você começará com saldo zero e sem movimentações.':'Serão carregados exemplos fictícios.'),()=>{state=d.action==='reset'?empty():demo();simulation=null;save();page='home'});break;}
});
document.addEventListener('submit',e=>{if(e.target.id!=='modal-form')return;e.preventDefault();try{let d=Object.fromEntries(new FormData(e.target));if(handler?.(d)){$('#dialog').close();render();toast('Pronto. Seu espaço foi atualizado.')}}catch(err){toast(err.message)}});
document.addEventListener('change',e=>{if(e.target.id==='type-filter'){filter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
function validBackup(s){const integer=n=>Number.isSafeInteger(n),str=x=>typeof x==='string',date=x=>str(x)&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&F.iso(F.parse(x))===x;
if(!s||s.version!==1||!date(s.start)||s.start>today||!integer(s.daily)||s.daily<0||!integer(s.reserve)||s.reserve<0||!Array.isArray(s.accounts)||!s.accounts.length||!Array.isArray(s.cards)||!Array.isArray(s.entries)||s.entries.length>10000||!Array.isArray(s.goals)||!Array.isArray(s.paid))return false;
if(!s.accounts.every(a=>str(a.id)&&str(a.name)&&integer(a.balance))||!s.cards.every(c=>str(c.id)&&str(c.name)&&integer(c.limit)&&c.limit>0&&integer(c.close)&&c.close>=1&&c.close<=31&&integer(c.due)&&c.due>=1&&c.due<=31))return false;
if(!s.entries.every(t=>str(t.id)&&str(t.name)&&integer(t.amount)&&t.amount>0&&date(t.date)&&['income','expense'].includes(t.type)&&['once','monthly','installments'].includes(t.repeat)&&integer(t.count)&&t.count>0&&t.count<=360&&str(t.category)&&(!t.kind||['income','expense','daily','saving'].includes(t.kind))&&(!t.until||date(t.until)&&t.until>=t.date)&&s.accounts.some(a=>a.id===t.account)&&(!t.card||t.type==='expense'&&s.cards.some(c=>c.id===t.card))))return false;
if(!s.goals.every(g=>str(g.id)&&str(g.name)&&integer(g.target)&&g.target>0&&integer(g.saved)&&g.saved>=0&&date(g.date))||!s.paid.every(str))return false;return [s.accounts,s.cards,s.entries,s.goals].every(a=>new Set(a.map(x=>x.id)).size===a.length)}
$('#import-file').addEventListener('change',async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Arquivo muito grande.');let imported=JSON.parse(await file.text());if(!validBackup(imported))throw Error('Backup inválido ou incompatível. Nada foi alterado.');confirmAction('Restaurar este backup?',`Substituir os dados atuais por ${imported.entries.length} movimentações, ${imported.accounts.length} contas e ${imported.goals.length} economias?`,()=>{state=imported;simulation=null;save();page='home'})}catch(err){toast(err.message)}e.target.value=''});
render();save();


